REVOKE INSERT,UPDATE ON public.user_progress FROM authenticated;
CREATE FUNCTION public.record_playback(_lesson uuid,_position int) RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.user_progress; duration int; elapsed int; next_pos int; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT duration_sec INTO duration FROM lessons WHERE id=_lesson; IF duration IS NULL THEN RAISE EXCEPTION 'Lesson not found'; END IF; INSERT INTO user_progress(user_id,lesson_id) VALUES(auth.uid(),_lesson) ON CONFLICT DO NOTHING; SELECT * INTO p FROM user_progress WHERE user_id=auth.uid() AND lesson_id=_lesson FOR UPDATE; elapsed=least(15,greatest(0,extract(epoch FROM now()-p.updated_at)::int)); next_pos=p.max_watched_sec; IF _position>=p.max_watched_sec AND _position<=p.max_watched_sec+elapsed+2 THEN next_pos=least(_position,duration); END IF; UPDATE user_progress SET max_watched_sec=next_pos,updated_at=now() WHERE user_id=auth.uid() AND lesson_id=_lesson; RETURN next_pos; END $$;
REVOKE ALL ON FUNCTION public.record_playback FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.record_playback TO authenticated;